    # Logout does NOT submit the exam: the session is suspended (kept open) so
    # logging in again continues it with the same cumulative risk.  Submitting
    # is POST /student/session/stop (the exam page's Submit button).
    try: current_app.session_manager.suspend_session(current_user.id)
    except Exception: pass
    logout_user()
