  if(force || !csrfTokenPromise){
    csrfTokenPromise = origFetch('/api/csrf-token', {credentials:'same-origin'})
      .then(r => r.ok ? r.json() : {csrf_token:null})
      .then(d => d.csrf_token)
      .catch(() => null)
      // a failed token fetch is NOT cached (it used to be, which silently
      // broke every later POST for the rest of the exam)
      .then(t => { if(!t) csrfTokenPromise = null; return t; });
  }
  return csrfTokenPromise;
}
