function evalStreamState(o) {
  const liveMs = o.liveMs || 4000, disconnectMs = o.disconnectMs || 15000;
  if (o.sessionLost) return { state: 'session_lost', label: 'Session lost', cls: 'red' };
  if (!o.lastOk) {
    return (o.fails > 0)
      ? { state: 'reconnecting', label: 'Connecting…', cls: 'amber' }
      : { state: 'starting', label: 'Starting…', cls: 'amber' };
  }
  const age = o.now - o.lastOk;
  if (age < liveMs) return { state: 'live', label: 'Live', cls: 'green' };
  if (age >= disconnectMs) return { state: 'disconnected', label: 'Disconnected', cls: 'red' };
  if (o.lastStatus >= 500) return { state: 'server_error', label: 'Server error', cls: 'red' };
