def _ensure_started(self):
    if self._threads:
        return
    for i in range(self.n_threads):
        t = threading.Thread(target=self._loop, daemon=True, name=f"{self._name}-{i}")
        t.start()
        self._threads.append(t)

def backlog(self) -> int:
    """Workers waiting for this scheduler right now (0 = it keeps up)."""
    with self._cv:
        return len(self._ready)

def _loop(self):
    while True:
        with self._cv:
            while not self._ready and not self._stop:
                self._cv.wait(timeout=1.0)
            if self._stop:
                return
            w = self._ready.popleft()
            k = id(w)
            self._queued.discard(k)
            self._running.add(k)
        try:
            getattr(w, self._run_attr)()
            self.processed += 1

