    """fast_face=False (AI_ASYNC=0 / no fast face path): AI frames at the YOLO cadence.
    watched=True: this student is open in a proctor's detail view (preview priority)."""
    out = None
    for limit, p in TIERS:
        if active_students <= limit:
            out = dict(p)
            break
