def _stat(key, n=1):
    with _DB_STATS_LOCK:
        DB_STATS[key] += n

def _run_job(fn, args, kwargs):
    for attempt in range(3):
        try:
            fn(*args, **kwargs)
            _stat("done")
            return
        except Exception as exc:                      # noqa: BLE001
            if type(exc).__name__ in _TRANSIENT and attempt < 2:
                _stat("retried")
                time.sleep(0.05 * (4 ** attempt))
                continue
            _stat("failed")
            log.warning("[DBWriter] job %s failed: %s: %s",
                        getattr(fn, "__name__", fn), type(exc).__name__, exc)

def _db_writer_loop():
    while True:
        job = _DB_WRITE_QUEUE.get()
        try:
            if job is not None:
                fn, args, kwargs = job
                _run_job(fn, args, kwargs)
        finally:
            _DB_WRITE_QUEUE.task_done()

def _ensure_db_writer_started():
    global _DB_WRITER_STARTED
    if _DB_WRITER_STARTED:
        return
    with _DB_WRITER_LOCK:
        if not _DB_WRITER_STARTED:
            threading.Thread(target=_db_writer_loop, daemon=True,
                             name="db-writer").start()
            _DB_WRITER_STARTED = True

def _enqueue_db_write(fn, *args, **kwargs):
    """Queue a persistence job.  If the bounded queue is full the job runs
    inline (slower, but events/evidence are never silently dropped)."""
    _ensure_db_writer_started()
    _stat("queued")
    try:
        _DB_WRITE_QUEUE.put_nowait((fn, args, kwargs))
    except queue.Full:
        _stat("inline")
        _run_job(fn, args, kwargs)

def flush_db_writes(timeout: float = 10.0) -> bool:
    """Block until every queued persistence job finished (tests / shutdown)."""
    end = time.time() + timeout
    while time.time() < end:
        if _DB_WRITE_QUEUE.unfinished_tasks == 0:
            return True
        time.sleep(0.02)
    return _DB_WRITE_QUEUE.unfinished_tasks == 0

