def _decay_to(self, now: float):
    dt = max(0.0, min(now - self._risk_ts, 3600.0))
    self._risk_ts = now
    if dt > 0 and self._risk_terms:
        f = 0.5 ** (dt / R.RISK_HALF_LIFE_SECS)
        for k in list(self._risk_terms):
            v = self._risk_terms[k] * f
            if v < 0.004:
                del self._risk_terms[k]
            else:
                self._risk_terms[k] = v

def _risk_at(self, now: float) -> float:
    with self._lock:
        self._decay_to(now)
        return float(min(1.0, sum(self._risk_terms.values())))

