def _episode_continues(last_active: float, absent_obs: int, now: float) -> bool:
    """Is this positive observation part of the episode already counted?
      * >= 2 frames showed the signal absent -> original rule (gap <= CONTINUITY_GAP)
      * exactly 1 absent frame (single detector miss) or none at all (sparse
        AI sampling) -> same episode, unless nothing was observed for
        EPISODE_UNOBSERVED_MAX seconds."""
    if last_active <= 0:
        return False
    gap = now - last_active
    if absent_obs >= 2:
        return gap <= CONTINUITY_GAP
    return gap <= max(CONTINUITY_GAP, EPISODE_UNOBSERVED_MAX)

