def _angles_from_matrix(mat):
    try:
        mat = np.asarray(mat, dtype=float)
        if mat.shape != (4, 4) or not np.isfinite(mat).all():
            return None
        # Preserve the existing axis convention; reject invalid transforms.
        if abs(mat[2, 1]) > 1.001:
            return None
        # Axis convention retained from the previous implementation:
        # pitch uses -R[2,1], yaw uses R[2,0]/R[2,2]. Roll is the in-plane
        # rotation around the camera axis and does not alter those signs.
        return (float(np.degrees(np.arcsin(np.clip(-mat[2, 1], -1, 1)))),
                float(np.degrees(np.arctan2(mat[2, 0], mat[2, 2]))),
                float(np.degrees(np.arctan2(mat[1, 0], mat[0, 0]))))

def _median_neutral(rows):
    """Median of calibration samples; blendshape columns may be NaN (not available)."""
    rows = np.asarray(rows, dtype=float)
    out = np.median(rows[:, :5], axis=0)
    default = np.array([NEUTRAL_LOOK_UP, NEUTRAL_LOOK_DOWN, NEUTRAL_BLINK])
    bs = rows[:, 5:8] if rows.shape[1] >= 8 else np.full((len(rows), 3), np.nan)
    med = default.copy()
    for k in range(3):
        col = bs[:, k][np.isfinite(bs[:, k])]
        if col.size:
            med[k] = float(np.median(col))
    return np.concatenate([out, med])

