def _already_seen(box, seen, iou_thresh=0.50) -> bool:
    ax, ay, aw, ah = box
    for sx, sy, sw, sh in seen:
        ix = max(0, min(ax+aw, sx+sw) - max(ax, sx))
        iy = max(0, min(ay+ah, sy+sh) - max(ay, sy))
        inter = ix * iy
        union = aw*ah + sw*sh - inter
        if union > 0 and inter/union > iou_thresh:
            return True
    return False

def _count_unique_boxes(boxes, iou_thresh=0.45) -> int:
    """Count boxes after merging ones that overlap (same object seen at
    multiple inference scales). Used so one real person is counted once."""
    kept = []
    for b in boxes:
        if not _already_seen(b, kept, iou_thresh):
            kept.append(b)
    return len(kept)

