def buffer_score(self) -> float:
    """Fraction of recent buffer slots that had a phone signal."""
    if not self._buffer:
        return 0.0
    return float(np.mean(list(self._buffer)))

def is_confirmed(self) -> bool:
    """True only when track has enough evidence over multiple frames."""
    return (
        len([t for t in self._positive_times if time.time() - t <= POSITIVE_WINDOW_SECS]) >= MIN_POSITIVE_OBSERVATIONS
        and self.positive_observation_count >= MIN_POSITIVE_OBSERVATIONS
        and self.buffer_score >= CONFIRM_THRESHOLD
        and self.miss_count < GRACE_FRAMES
    )

def is_stale(self) -> bool:
    """Track should be discarded."""
    return self.miss_count >= GRACE_FRAMES

def confidence(self) -> float:
    """Overall detection confidence for display."""
    return min(1.0, self.buffer_score * 1.1)

def temporal_confidence(self) -> float:
    now = time.time()
    recent = sum(1 for t in self._positive_times if now - t <= POSITIVE_WINDOW_SECS)
    return float(np.clip(recent / float(MIN_POSITIVE_OBSERVATIONS), 0.0, 1.0))

def _effective_score(yolo_conf: float, ver_score: float, decision: str) -> float:
    """
    Combine YOLO confidence and verifier score into a 0–1 value
    for the buffer. REJECT decisions suppress the score heavily.
    """
    base = (yolo_conf * 0.55 + ver_score * 0.45)
    if decision == "REJECT":
        base *= 0.25
    elif decision == "MONITOR":
        base *= 0.70
    # ACCEPT: no penalty
    return float(np.clip(base, 0, 1))

def metadata(track):
    return {
        "last_detector_seen_at": track.last_seen,
        "last_positive_seen_at": track.last_seen,
        "currently_visible": track.miss_count == 0,
        "temporarily_missing": track.miss_count > 0,
        "track_age_seconds": max(0.0, time.time() - track.created_at),
    }

