def _load_yamnet(self):
    t0 = time.time()
    try:
        if not os.path.isfile(os.path.join(self.YAMNET_LOCAL_DIR, "saved_model.pb")):
            raise FileNotFoundError(
                f"no saved_model.pb in {os.path.abspath(self.YAMNET_LOCAL_DIR)}")
        os.environ.setdefault("TF_CPP_MIN_LOG_LEVEL", "2")
        try:
            import tensorflow as tf
        except ImportError as exc:
            raise RuntimeError(f"tensorflow is not installed ({exc})") from exc
        self.tf_version = tf.__version__
        classes = self._read_class_map()
        model = tf.saved_model.load(self.YAMNET_LOCAL_DIR)

def _read_class_map(self) -> list[str]:
    for path in self.YAMNET_CLASS_MAP_CANDIDATES:
        if path and os.path.isfile(path):
            with open(path, newline="", encoding="utf-8") as f:
                rows = list(csv.DictReader(f))
            names = [r["display_name"] for r in rows]
            if len(names) != 521:
                raise RuntimeError(f"class map {path} has {len(names)} rows, expected 521")
            self.class_map_path = os.path.abspath(path)
            return names
    raise FileNotFoundError(
        "YAMNet class map (yamnet_class_map.csv, 521 rows) not found; looked in: "
        + ", ".join(p for p in self.YAMNET_CLASS_MAP_CANDIDATES if p))

def _resolve_groups(self):
    index = {n: i for i, n in enumerate(self._classes)}
    self._groups, self.missing_class_names = {}, []
    for group, names in YAMNET_GROUP_NAMES.items():
        ids = []
        for n in names:
            if n in index:
                ids.append(index[n])
            else:
                self.missing_class_names.append(n)
        self._groups[group] = ids

def _load_sounddevice(self):
    try:
        import sounddevice as sd
        self._sd = sd
    except Exception:                                          # noqa: BLE001
        self._sd = None

def start(self):
    if self._sd is None or self._running:
        return
    self._running = True
    self._thread = threading.Thread(target=self._run, daemon=True)
    self._thread.start()

def stop(self):
    self._running = False
    if self._thread:
        self._thread.join(timeout=2)

def get_result(self) -> dict:
    with self._lock:
        return dict(self._result)

def _run(self):
    def _cb(indata, frames, time_info, status):
        chunk = indata[:, 0].copy() if indata.ndim > 1 else indata.copy()
        try:
            self._audio_q.put_nowait(chunk)
        except queue.Full:
            pass
    try:
        buf = np.zeros(0, np.float32)
        with self._sd.InputStream(samplerate=self._sr, channels=1, dtype="float32",
                                  blocksize=CHUNK_SAMPLES, callback=_cb):
            while self._running:
                try:
                    buf = np.concatenate([buf, self._audio_q.get(timeout=1.0)])[-2 * SAMPLE_RATE:]

def _cb(indata, frames, time_info, status):
    chunk = indata[:, 0].copy() if indata.ndim > 1 else indata.copy()
    try:
        self._audio_q.put_nowait(chunk)
    except queue.Full:
        pass

def classify_waveform(self, samples, sample_rate: int) -> dict:
    x = np.asarray(samples, dtype=np.float32).reshape(-1)
    if x.size == 0:
        return dict(_SAFE_RESULT, backend=self.backend, decision="empty")
    x = np.nan_to_num(x, nan=0.0, posinf=0.0, neginf=0.0)
    if sample_rate and sample_rate != SAMPLE_RATE:
        n_out = max(1, int(round(x.size * SAMPLE_RATE / float(sample_rate))))
        x = np.interp(np.linspace(0, x.size - 1, n_out), np.arange(x.size), x).astype(np.float32)
    x = np.clip(x, -1.0, 1.0)[-int(MAX_WINDOW_SECS * SAMPLE_RATE):]
    rms = float(np.sqrt(np.mean(x ** 2)))
    if self._model is not None:
        res = self._classify_yamnet(x, rms)
    else:
        res = self._classify_energy(x, rms)

def _classify_yamnet(self, x: np.ndarray, rms: float) -> dict:
    base = {"audio_level": round(rms, 4), "backend": "YAMNet",
            "window_secs": round(x.size / SAMPLE_RATE, 2)}
    if x.size < YAMNET_MIN_SAMPLES:
        return dict(base, event="insufficient_audio", confidence=0.0,
                    is_suspicious=False, inference_ran=False,
                    decision="window shorter than one YAMNet patch (0.975 s)")
    if rms < self.rms_floor:
        # digital silence: skip inference (saves CPU); the result says so
        return dict(base, event="silence", confidence=1.0, is_suspicious=False,
                    inference_ran=False, decision="rms_gate_silence")
    t0 = time.perf_counter()
    with self._classify_lock:
        out = self._model(self._tf.constant(x))

def _classify_energy(self, x: np.ndarray, rms: float) -> dict:
    """Energy + variance heuristic.  NOT YAMNet — labelled as a fallback."""
    event, conf, sus = "silence", 0.0, False
    if rms > 0.025:
        event, conf, sus = "speech", min(1.0, rms * 20), True
    elif rms > 0.008 and float(np.var(x)) > 5e-5:
        event, conf = "whispering", min(1.0, rms * 40)
        sus = conf > 0.35
    return {"event": event, "confidence": round(conf, 3), "is_suspicious": sus,
            "audio_level": round(rms, 4), "backend": "energy-variance fallback",
            "inference_ran": False, "decision": "energy-variance",
            "window_secs": round(x.size / SAMPLE_RATE, 2)}

def get_shared_analyzer() -> "AudioAnalyzer":
    global _shared_analyzer
    if _shared_analyzer is None:
        with _shared_analyzer_lock:
            if _shared_analyzer is None:
                _shared_analyzer = AudioAnalyzer()
