class AudioPipeline:
    def __init__(self, get_worker, analyzer_getter=None):
        if analyzer_getter is None:
            from modules.detection.audio_analyzer import get_shared_analyzer
            analyzer_getter = get_shared_analyzer
        self._get_worker = get_worker
        self._get_analyzer = analyzer_getter
        self._bufs: dict[int, np.ndarray] = {}
        self._new: dict[int, int] = {}
        self._pending: "collections.OrderedDict[int, bool]" = collections.OrderedDict()
        self._cv = threading.Condition()
        self._thread = None
        self._stop = False
        self.submitted = 0

def _ensure_started(self):
    if self._thread is None:
        self._thread = threading.Thread(target=self._loop, daemon=True, name="audio-infer")
        self._thread.start()

def warmup(self):
    """Load the analyzer now (call from a background thread at startup)."""
    return self._get_analyzer().status()

def _loop(self):
    while not self._stop:
        with self._cv:
            while not self._pending and not self._stop:
                self._cv.wait(timeout=1.0)
            if self._stop:
                return
            sid, _ = self._pending.popitem(last=False)
            window = self._bufs.get(sid, np.zeros(0, np.float32))[-int(WINDOW_SECS * SR):].copy()
            self._new[sid] = 0
        worker = self._get_worker(sid)
        if worker is None:
            self.forget(sid)
            continue

def stats(self) -> dict:
    with self._cv:
        return {"submitted": self.submitted, "classified": self.classified,
                "coalesced": self.coalesced, "errors": self.errors,
                "last_error": self.last_error, "last_infer_ms": self.last_infer_ms,
                "pending": len(self._pending), "buffers": len(self._bufs)}

def wait_idle(self, timeout: float = 10.0) -> bool:
    end = time.time() + timeout
    while time.time() < end:
        with self._cv:
            if not self._pending:
                return True
        time.sleep(0.02)
    return False

def _correct_brightness(self, frame: np.ndarray) -> np.ndarray:
    """Gamma correction to normalise brightness toward target."""
    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    mean = float(np.mean(gray))
    if mean < 5:
        return frame
    gamma = np.log(self._target_lum / 255.0) / np.log(mean / 255.0 + 1e-9)
    gamma = float(np.clip(gamma, 0.4, 3.0))
    lut   = np.array([
        min(255, int((i / 255.0) ** gamma * 255))
        for i in range(256)
    ], dtype=np.uint8)
    return cv2.LUT(frame, lut)

def _apply_clahe(self, frame: np.ndarray) -> np.ndarray:
    """Apply CLAHE to the L channel of LAB colour space."""
    lab = cv2.cvtColor(frame, cv2.COLOR_BGR2LAB)
    lab[:, :, 0] = self._clahe.apply(lab[:, :, 0])
    return cv2.cvtColor(lab, cv2.COLOR_LAB2BGR)

def _sharpen(self, frame: np.ndarray) -> np.ndarray:
    """Mild unsharp masking to improve edge definition."""
    blurred  = cv2.GaussianBlur(frame, (3, 3), 0)
    sharpened = cv2.addWeighted(frame, 1.4, blurred, -0.4, 0)
    return np.clip(sharpened, 0, 255).astype(np.uint8)

