    ratio = h / (w + 1e-6)
    if ASPECT_PORTRAIT_MIN <= ratio <= ASPECT_PORTRAIT_MAX:
        c = (ASPECT_PORTRAIT_MIN + ASPECT_PORTRAIT_MAX) / 2
        return float(1.0 - abs(ratio - c) / c)
    inv = 1.0 / (ratio + 1e-6)
    if ASPECT_PORTRAIT_MIN <= inv <= ASPECT_PORTRAIT_MAX:
        c = (ASPECT_PORTRAIT_MIN + ASPECT_PORTRAIT_MAX) / 2
        return float(0.9 - abs(inv - c) / c)
