def _size(self, rw, rh, fw, fh, is_clipped=False):
    area_frac = (rw * rh) / (fw * fh + 1e-6)
    min_frac  = AREA_MIN_FRAC * 0.38 if is_clipped else AREA_MIN_FRAC
    if min_frac <= area_frac <= AREA_MAX_FRAC:
        return float(1.0 - min(1.0, abs(np.log(area_frac / 0.07 + 1e-9)) * 0.4))
    elif area_frac < min_frac:
        return float(max(0.12, area_frac / min_frac * 0.72))
    return float(max(0.0, 1.0 - (area_frac - AREA_MAX_FRAC) / 0.2))

def _r(score, checks, decision):
    return {"score": round(float(score), 4), "decision": decision,
            "checks": {k: round(v, 3) for k, v in checks.items()}}

def recent_bypass_count(self, window_secs: float = 60.0) -> int:
    """How many frames with any bypass flag in the last window_secs."""
    cutoff = time.time() - window_secs
    return sum(1 for f in self._history if f["ts"] >= cutoff and f["flags"])

def _check_edge_phones(self, candidates, confirmed, w, h) -> bool:
    """Any candidate bounding box touching the frame edge."""
    margin_x = int(w * EDGE_MARGIN_FRAC)
    margin_y = int(h * EDGE_MARGIN_FRAC)
    all_dets  = candidates + confirmed
    for d in all_dets:
        x, y, bw, bh = d["box"]
        if x <= margin_x or y <= margin_y:
            return True
        if (x + bw) >= (w - margin_x) or (y + bh) >= (h - margin_y):
            return True
    return False
